typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* createNode(int data) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return NULL;
    n->data = data;
    n->next = NULL;
    return n;
}

void singly_list_insert_head(SinglyNode** head, int val) {
    SinglyNode* n = (SinglyNode*)malloc(sizeof(SinglyNode));
    if (!n) return;
    n->data = val;
    n->next = *head;
    *head = n;
}

int singly_list_insert_head_status(SinglyNode** head, int val) {
    SinglyNode* n = (SinglyNode*)malloc(sizeof(SinglyNode));
    if (!n) return -1;
    n->data = val;
    n->next = *head;
    *head = n;
    return 0;
}

void singly_list_insert_tail(SinglyNode** head, int val) {
    SinglyNode* n = (SinglyNode*)malloc(sizeof(SinglyNode));
    if (!n) return;
    n->data = val;
    n->next = NULL;
    if (!*head) { *head = n; return; }
    SinglyNode* cur = *head;
    while (cur->next) cur = cur->next;
    cur->next = n;
}

int singly_list_delete_head(SinglyNode** head) {
    if (!head || !*head) return -1;
    SinglyNode* temp = *head;
    *head = (*head)->next;
    free(temp);
    return 0;
}

int singly_list_delete_value(SinglyNode** head, int val) {
    if (!head || !*head) return -1;
    if ((*head)->data == val) {
        SinglyNode* tmp = *head;
        *head = (*head)->next;
        free(tmp);
        return 0;
    }
    SinglyNode* cur = *head;
    while (cur->next && cur->next->data != val) cur = cur->next;
    if (!cur->next) return -1;
    SinglyNode* tmp = cur->next;
    cur->next = tmp->next;
    free(tmp);
    return 0;
}

void singly_list_reverse(SinglyNode** head) {
    SinglyNode* prev = NULL;
    SinglyNode* cur = *head;
    while (cur) {
        SinglyNode* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    *head = prev;
}

bool singly_list_has_cycle(const SinglyNode* head) {
    const SinglyNode* slow = head;
    const SinglyNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

SinglyNode* singly_list_find_middle(SinglyNode* head) {
    if (!head) return NULL;
    SinglyNode* slow = head;
    SinglyNode* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

