int stack_op_1(Stack* s, int element) {
    if (!s || s->top >= s->capacity) return -1;
    s->data[s->top++] = element;
    return 0;
}

int queue_op_1(Queue* q, int element) {
    if (!q || q->count >= q->capacity) return -1;
    q->data[q->tail] = element;
    q->tail = (q->tail + 1) % q->capacity;
    q->count++;
    return 0;
}

