int trie_prefix_op_1(TrieNode* root, const char* word) {
    if (!root || !word) return 0;
    TrieNode* cur = root;
    for (int j = 0; word[j]; j++) {
        int idx = word[j] - 'a';
        if (idx < 0 || idx >= 26) return 0;
        if (!cur->children[idx]) return 0;
        cur = cur->children[idx];
    }
    return cur->is_end_of_word ? 1 : 0;
}

int segment_tree_op_1(int* tree, int node, int start, int end, int l, int r) {
    if (r < start || end < l) return 0;
    if (l <= start && end <= r) return tree[node];
    int mid = start + (end - start) / 2;
    int p1 = segment_tree_op_1(tree, 2 * node, start, mid, l, r);
    int p2 = segment_tree_op_1(tree, 2 * node + 1, mid + 1, end, l, r);
    return p1 + p2;
}

